        return (data.length() > 1 && (data.startsWith("!") || data.startsWith("?")));
    }

public @Nullable XmlDeclaration asXmlDeclaration() {
        String data = getData();

        XmlDeclaration decl = null;
        String declContent = data.substring(1, data.length() - 1);
        // make sure this bogus comment is not immediately followed by another, treat as comment if so
        if (isXmlDeclarationData(declContent))
            return null;

        String fragment = "<" + declContent + ">";
        // use the HTML parser not XML, so we don't get into a recursive XML Declaration on contrived data
        Document doc = Parser.htmlParser().settings(ParseSettings.preserveCase).parseInput(fragment, baseUri());
        if (doc.body().children().size() > 0) {
            Element el = doc.body().child(0);
            decl = new XmlDeclaration(NodeUtils.parser(doc).settings().normalizeTag(el.tagName()), data.startsWith("!"));
            decl.attributes().addAll(el.attributes());
        }
        return decl;
    }

protected final boolean hasAttributes() {
        return value instanceof Attributes;
    }

@Override
    public final Attributes attributes() {
        ensureAttributes();
        return (Attributes) value;
    }

private void ensureAttributes() {
        if (!hasAttributes()) {
            Object coreValue = value;
            Attributes attributes = new Attributes();
            value = attributes;
            if (coreValue != null)
                attributes.put(nodeName(), (String) coreValue);
        }
    }

String coreValue() {
        return attr(nodeName());
    }

void coreValue(String value) {
        attr(nodeName(), value);
    }

@Override
    public String attr(String key) {
        if (!hasAttributes()) {
            return nodeName().equals(key) ? (String) value : EmptyString;
        }
        return super.attr(key);
    }

@Override
    public Node attr(String key, String value) {
        if (!hasAttributes() && key.equals(nodeName())) {
            this.value = value;
        } else {
            ensureAttributes();
            super.attr(key, value);
        }
        return this;
    }

@Override
    public boolean hasAttr(String key) {
        ensureAttributes();
        return super.hasAttr(key);
    }

@Override
    public Node removeAttr(String key) {
        ensureAttributes();
        return super.removeAttr(key);
    }

@Override
    public String absUrl(String key) {
        ensureAttributes();
        return super.absUrl(key);
    }

@Override
    public String baseUri() {
        return hasParent() ? parent().baseUri() : "";
    }

@Override
    protected void doSetBaseUri(String baseUri) {
        // noop
    }

@Override
    public int childNodeSize() {
        return 0;
    }

@Override
    public Node empty() {
        return this;
    }

@Override
    protected List<Node> ensureChildNodes() {
        return EmptyNodes;
    }

@Override
    protected LeafNode doClone(Node parent) {
        LeafNode clone = (LeafNode) super.doClone(parent);

        // Object value could be plain string or attributes - need to clone
        if (hasAttributes())
            clone.value = ((Attributes) value).clone();

        return clone;
    }

@Override
    public E set(int index, E element) {
        onContentsChanged();
        return super.set(index, element);
    }

@Override
    public boolean add(E e) {
        onContentsChanged();
        return super.add(e);
    }

@Override
    public void add(int index, E element) {
        onContentsChanged();
        super.add(index, element);
    }

@Override
    public E remove(int index) {
        onContentsChanged();
        return super.remove(index);
    }

@Override
    public boolean remove(Object o) {
        onContentsChanged();
        return super.remove(o);
    }

@Override
    public void clear() {
        onContentsChanged();
        super.clear();
    }

@Override
    public boolean addAll(Collection<? extends E> c) {
        onContentsChanged();
        return super.addAll(c);
    }

@Override
    public boolean addAll(int index, Collection<? extends E> c) {
        onContentsChanged();
        return super.addAll(index, c);
    }

@Override
    protected void removeRange(int fromIndex, int toIndex) {
        onContentsChanged();
        super.removeRange(fromIndex, toIndex);
    }

@Override
    public boolean removeAll(Collection<?> c) {
        onContentsChanged();
        return super.removeAll(c);
    }

@Override
    public boolean retainAll(Collection<?> c) {
        onContentsChanged();
        return super.retainAll(c);
    }

